// Translation interface
export interface SaveAlbumTranslations {
  // Navigation
  myAlbums: string;
  logOut: string;
  
  // Progress Tracking
  uploadProgress: string;
  overallProgress: string;
  ofComplete: string;
  uploading: string;
  processing: string;
  complete: string;
  failed: string;
  
  // Save Album Progress
  savingAlbum: string;
  movingFiles: string;
  
  // Media info
  video: string;
  image: string;
  error: string;
  remove: string;
  
  // Buttons
  saveAlbum: string;
  savingAlbumProgress: string;
  addMorePhotos: string;
  
  // Username prompt
  enterUsername: string;
  usernameExample: string;
  selectUsername: string;
  selectUsernameDigits: string;
  usernameError: string;
  usernameTakenError: string;
  
  // Photo summary
  photoSelected: string;
  photosSelected: string;
  
  // Debug
  debugLog: string;
}

